window.docContents[93].resolve({"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Section-2___2-heading-and-introduction-to-systematic-discussion/#Chapter2___Discussion_2___2_intro___heading-1":{"contents":"Let us now begin a systematic discussion of representation theory.\n\nLet k be a field. Unless stated otherwise, we will always assume that k is algebraically\nclosed, i.e., any nonconstant polynomial with coefficients in k has a root in k. The main\nexample is the field of complex numbers \\mathbb{C}, but we will also consider fields of\ncharacteristic p, such as the algebraic closure \\overline{\\mathbb{F}}_p of the finite field\n\\mathbb{F}_p of p elements.\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.2. Algebras\tSection 2.2 heading and introduction to systematic discussion","header":"Section 2.2 heading and introduction to systematic discussion","id":"/2___-Basic-notions-of-representation-theory/2___2___-Algebras/Section-2___2-heading-and-introduction-to-systematic-discussion/#Chapter2___Discussion_2___2_intro___heading-1"},"/6___-Quiver-representations/6___6___-Reflection-functors/Section-6___6-heading___-Reflection-functors/#Chapter6___Section6___6_heading___heading-1":{"contents":"","context":"Introduction to Representation Theory\t6. Quiver representations\t6.6. Reflection functors\tSection 6.6 heading: Reflection functors","header":"6.6. Reflection functors","id":"/6___-Quiver-representations/6___6___-Reflection-functors/Section-6___6-heading___-Reflection-functors/#Chapter6___Section6___6_heading___heading-1"}});
